package com.aadil.ecommerce.services;import com.aadil.ecommerce.UserRole;import com.aadil.ecommerce.dtos.InvitationDTO;import com.aadil.ecommerce.dtos.UserResponseDTO;import com.aadil.ecommerce.entities.AdminInvitationEntity;import com.aadil.ecommerce.entities.UserEntity;import com.aadil.ecommerce.enums.AdminRequestStatus;import com.aadil.ecommerce.enums.UserSortDirection;import com.aadil.ecommerce.enums.UserSortField;import com.aadil.ecommerce.exceptions.*;import com.aadil.ecommerce.repositories.AdminRepository;import com.aadil.ecommerce.repositories.UserRepository;import com.aadil.ecommerce.responses.PaginatedResponse;import lombok.RequiredArgsConstructor;import org.springframework.data.domain.Page;import org.springframework.data.domain.PageRequest;import org.springframework.data.domain.Pageable;import org.springframework.data.domain.Sort;import org.springframework.security.config.annotation.AlreadyBuiltException;import org.springframework.security.core.userdetails.UsernameNotFoundException;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import java.security.NoSuchAlgorithmException;import java.security.SecureRandom;import java.time.LocalDateTime;import java.util.*;@Service@RequiredArgsConstructorpublic class AdminService {    private final AdminRepository adminRepository;    private final UserRepository userRepository;    private UserResponseDTO mapToDTO (UserEntity user){        return new UserResponseDTO(user.getId(),user.getName(),user.getEmail(),user.getRole());    }    public PaginatedResponse<List<UserResponseDTO>> getAllUsers (String search, int pageNumber, int size, UserSortField sortField, UserSortDirection sortDirection){        if (search != null && search.isBlank()){            search =  search.trim();        }        if (pageNumber < 0){            throw new InvalidCredentialException("PageNumber should NOT be 0");        }        if (pageNumber > 30){            throw new InvalidCredentialException("PageNumber should NOT exceed 30");        }        if (size < 1){            throw new InvalidCredentialException("Size should NOT be below 1");        }        if (size > 30){            throw new InvalidCredentialException("Size should NOT exceed 30");        }        if (sortField == null){            sortField = UserSortField.ID;        }        if (sortDirection == null){            sortDirection = UserSortDirection.ASC;        }        Sort.Direction direction = sortDirection == UserSortDirection.ASC?                Sort.Direction.ASC:Sort.Direction.DESC;        Sort sort = Sort.by(new Sort.Order(direction,sortField.getUserSortField()));        Pageable pageable = PageRequest.of(pageNumber,size,sort);        Page<UserEntity> user;        if (search == null || search.isBlank()){            user = userRepository.findAll(pageable);        }        else {            user = userRepository.findByEmailContainingIgnoreCaseOrNameContainingIgnoreCase(search,search,pageable);        }        List<UserResponseDTO> contents = user.getContent().stream().map(this::mapToDTO).toList();        return new PaginatedResponse<>(contents,user.getNumber(),user.getSize(),user.getTotalElements(),user.getTotalPages(),user.isLast());    }    public void deleteUsersById (List<Long>ids, boolean confirm){        if (ids == null || ids.isEmpty()){            throw new IllegalArgumentException("At least one ID is required");        }        if (ids.contains(null)){            throw new IllegalArgumentException("Ids cannot be NULL");        }        Set<Long> duplicateIds = new HashSet<>();        for (Long id: ids) {            if (!duplicateIds.add(id)) {                throw new UserAlreadyExistsException("Duplicate ID found: " + id);            }        }        List<UserEntity> users = userRepository.findAllById(ids);        if (users.size() != ids.size()) {            throw new IllegalArgumentException("User NOT exists with this ID");        }        if (!confirm){            throw new IllegalArgumentException("Confirmation required to delete an User");        }        userRepository.deleteAllById(ids);    }    public void deleteUser (Long id, boolean confirm){        if (!confirm){            throw new RuntimeException("Type confirm to proceed");        }        UserEntity user = userRepository.findById(id).orElseThrow(() -> new UsernameNotFoundException("User is NOT found: " + id));        userRepository.deleteById(user.getId());    }    public UserResponseDTO promoteToAdmin (Long id){        UserEntity user = userRepository.findById(id).orElseThrow(()->new ResourceNotFoundException("Resource NOT found: "+id));        user.setRole(UserRole.ADMIN);        UserEntity savedUser = userRepository.save(user);        return mapToDTO(savedUser);    }    private String generateInvitation (){        SecureRandom secureRandom = new SecureRandom();        byte[] randomBytes = new byte[32];        secureRandom.nextBytes(randomBytes);        return Base64.getUrlEncoder().withoutPadding().encodeToString(randomBytes);    }    private String invitationHash (String rawInviteToken) throws NoSuchAlgorithmException{        MessageDigest messageDigest = MessageDigest.getInstance("SHA-256");        byte[] digestMessage = messageDigest.digest(rawInviteToken.getBytes(StandardCharsets.UTF_8));        return HexFormat.of().formatHex(digestMessage);    }    @Transactional    public String invitationCreation (InvitationDTO dto) throws NoSuchAlgorithmException {        String email = dto.getEmail().trim().toLowerCase();        UserEntity user = userRepository.findByEmail(email).orElseThrow(()->new ResourceNotFoundException("User email NOT found: "+email));        if (user.getRole() == UserRole.ADMIN){            throw new UserAlreadyAnAdminException("This user is already an ADMIN");        }        if (adminRepository.existsByUserAndAdminRequestStatus(user,AdminRequestStatus.PENDING)) {            throw new RequestPendingException("This user has already a PENDING request");        }        String rawToken = generateInvitation();        String hashedToken = invitationHash(rawToken);        AdminInvitationEntity invitation = new AdminInvitationEntity();        invitation.setUser(user);        invitation.setTokenHash(hashedToken);        invitation.setAdminRequestStatus(AdminRequestStatus.PENDING);        invitation.setExpiresAt(LocalDateTime.now().plusHours(24));        adminRepository.save(invitation);        return rawToken;    }}